<?php
require_once __DIR__ . '/config.php'; require_login(); require_admin();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$contact=trim((string)($_POST['contact_person']??''));$phone=trim((string)($_POST['phone']??''));$email=trim((string)($_POST['email']??''));$address=trim((string)($_POST['address']??''));if($name===''||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)))flash('Nama supplier wajib diisi dan email harus valid.','error');else try{if($id){$s=$pdo->prepare('UPDATE suppliers SET name=?,contact_person=?,phone=?,email=?,address=? WHERE id=?');$s->execute([$name,$contact?:null,$phone?:null,$email?:null,$address?:null,$id]);}else{$s=$pdo->prepare('INSERT INTO suppliers(name,contact_person,phone,email,address) VALUES(?,?,?,?,?)');$s->execute([$name,$contact?:null,$phone?:null,$email?:null,$address?:null]);}flash('Supplier disimpan.');}catch(Throwable $e){flash('Gagal menyimpan supplier.','error');}redirect('suppliers.php');}
if(isset($_GET['delete'])){try{$pdo->prepare('DELETE FROM suppliers WHERE id=?')->execute([(int)$_GET['delete']]);flash('Supplier dihapus.');}catch(Throwable $e){flash('Supplier gagal dihapus.','error');}redirect('suppliers.php');}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM suppliers WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}
$q=trim((string)($_GET['q']??''));$s=$pdo->prepare("SELECT s.*,COUNT(ps.product_id) product_count FROM suppliers s LEFT JOIN product_suppliers ps ON ps.supplier_id=s.id WHERE (?='' OR s.name LIKE ? OR s.phone LIKE ?) GROUP BY s.id ORDER BY s.name");$s->execute([$q,"%$q%","%$q%"]);$rows=$s->fetchAll();$pageTitle='Supplier';require 'partials_header.php';?>
<section class="panel"><div class="panel-heading"><h2><?= $edit?'Edit supplier':'Tambah supplier' ?></h2></div><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div><label>Nama supplier *</label><input name="name" required value="<?= e($edit['name']??'') ?>"></div><div><label>Kontak person</label><input name="contact_person" value="<?= e($edit['contact_person']??'') ?>"></div><div><label>Telepon</label><input name="phone" value="<?= e($edit['phone']??'') ?>"></div><div><label>Email</label><input type="email" name="email" value="<?= e($edit['email']??'') ?>"></div><div class="wide"><label>Alamat</label><input name="address" value="<?= e($edit['address']??'') ?>"></div><div class="wide"><button class="btn primary">Simpan supplier</button> <?php if($edit): ?><a class="btn" href="suppliers.php">Batal</a><?php endif; ?></div></form></section>
<section class="panel"><div class="panel-heading"><h2>Daftar supplier</h2><form class="filters compact"><input name="q" placeholder="Cari nama/telepon" value="<?= e($q) ?>"><button class="btn">Cari</button></form></div><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Kontak</th><th>Telepon / Email</th><th>Produk terhubung</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['name']) ?></strong><small><?= e($r['address']) ?></small></td><td><?= e($r['contact_person']) ?></td><td><?= e($r['phone']) ?><small><?= e($r['email']) ?></small></td><td><?= $r['product_count'] ?></td><td class="actions"><a href="?edit=<?= $r['id'] ?>">Edit</a><a class="danger-link" href="?delete=<?= $r['id'] ?>" onclick="return confirm('Hapus supplier?')">Hapus</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="empty">Belum ada supplier.</td></tr><?php endif; ?></tbody></table></div></section><?php require 'partials_footer.php'; ?>
